import{_ as t,o,c as a,a6 as r}from"./chunks/framework.DIp0zHSV.js";const s="/dev/img/theme-lab/start.webp",l="/dev/img/theme-lab/palette-seed.webp",n="/dev/img/theme-lab/preview.webp",i="/dev/img/theme-lab/export.webp",f=JSON.parse(`{"title":"HA-LCARS Theme Lab","description":"Build your own HA-LCARS theme profile in the LCARdS panel's HA-LCARS Theme Lab: palettes for HA's five colour roles, LCARS chrome, state colours, a live preview, and YAML to add to HA-LCARS.","frontmatter":{"description":"Build your own HA-LCARS theme profile in the LCARdS panel's HA-LCARS Theme Lab: palettes for HA's five colour roles, LCARS chrome, state colours, a live preview, and YAML to add to HA-LCARS."},"headers":[],"relativePath":"configuration/ha-lcars-theme-lab.md","filePath":"configuration/ha-lcars-theme-lab.md","lastUpdated":1792162559000}`),h={name:"configuration/ha-lcars-theme-lab.md"};function d(c,e,m,u,g,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ha-lcars-theme-lab" tabindex="-1">HA-LCARS Theme Lab <a class="header-anchor" href="#ha-lcars-theme-lab" aria-label="Permalink to &quot;HA-LCARS Theme Lab&quot;">​</a></h1><p>The <strong>HA-LCARS Theme Lab</strong> builds your own theme profile for <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS</a>, the same kind as the <a href="./ha-lcars-theme-profiles.html">LCARdS profiles</a> HA-LCARS ships. Start from any HA-LCARS theme, change its colours, check the result, and copy the YAML into HA-LCARS.</p><ul><li><strong>Five full palettes:</strong> the colour roles Home Assistant&#39;s own screens use (primary, neutral, warning, danger, success), each an 11-tone scale, with separate light and dark versions if you want them.</li><li><strong>Readable by design:</strong> button text colours are checked for contrast and corrected automatically.</li><li><strong>Everything else in one place:</strong> the LCARS chrome (sidebar, header, status bars), legacy HA colours and the colour of every entity state.</li></ul><p>Open it from the LCARdS panel: <strong>Theme Studio &gt; HA-LCARS Theme Lab</strong>.</p><p><img src="'+s+'" alt="The HA-LCARS Theme Lab: the Start section with a theme to load, below the Configuration and Preview &amp; Export switch"></p><h2 id="_1-start-from-a-theme" tabindex="-1">1. Start from a theme <a class="header-anchor" href="#_1-start-from-a-theme" aria-label="Permalink to &quot;1. Start from a theme&quot;">​</a></h2><ul><li><strong>Load from HA-LCARS:</strong> pick a theme. Ones installed on your Home Assistant are marked <em>installed on this HA</em>; the others are reference copies bundled with LCARdS. A good start is one of the LCARdS profiles, <strong>LCARS Picard [LCARdS Red Accent]</strong> or <strong>[LCARdS Blue Accent]</strong>.</li><li><strong>Paste theme YAML:</strong> bring in a theme you already have, including one you made here earlier.</li><li>Give your theme a <strong>Theme Name</strong>. That is the name you&#39;ll pick in Home Assistant later.</li></ul><h2 id="_2-palette-seed-the-five-colour-roles" tabindex="-1">2. Palette Seed: the five colour roles <a class="header-anchor" href="#_2-palette-seed-the-five-colour-roles" aria-label="Permalink to &quot;2. Palette Seed: the five colour roles&quot;">​</a></h2><p><img src="'+l+'" alt="Palette Seed: the Primary role with its 11-tone light and dark scales, button badges and contrast notes, and the other four roles below"></p><p>Each role (<strong>Primary</strong>, <strong>Neutral</strong>, <strong>Orange (Warning)</strong>, <strong>Red (Danger)</strong>, <strong>Green (Success)</strong>) gets a full scale of tones, from darkest to lightest. For each role, choose where it comes from:</p><ul><li><strong>None:</strong> leave it to Home Assistant&#39;s own default.</li><li><strong>LCARdS Palettes:</strong> use one of the LCARdS colour families (orange, gray, blue, green, yellow).</li><li><strong>Custom:</strong> set the tones yourself.</li><li><strong>Imported:</strong> keep the scale of the theme you loaded.</li></ul><p>Tips:</p><ul><li>Turn on separate <strong>dark mode</strong> tones for a role when light and dark mode should look different.</li><li>The small <strong>A</strong>, <strong>F</strong>, <strong>T</strong> and <strong>O</strong> badges show which tone becomes a button&#39;s background or text (open <em>The A/F/T/O badges</em> for details).</li><li>When a tone wouldn&#39;t be readable as button text, the lab picks a readable one on export and explains it under the role.</li></ul><h2 id="_3-the-other-sections" tabindex="-1">3. The other sections <a class="header-anchor" href="#_3-the-other-sections" aria-label="Permalink to &quot;3. The other sections&quot;">​</a></h2><ul><li><strong>HA-LCARS &amp; Legacy HA Semantic Colours:</strong> the LCARS chrome (sidebar, header, status bars, buttons) and the older Home Assistant colour variables. Anything you leave unset keeps HA-LCARS&#39;s or Home Assistant&#39;s default.</li><li><strong>Domain &amp; State Colours:</strong> the colour of an entity&#39;s icon in each state, per domain (lights, locks, climate and more), with a global fallback.</li><li><strong>Advanced / Raw Overrides:</strong> any other theme variable, by name.</li></ul><h2 id="_4-preview-and-export" tabindex="-1">4. Preview and export <a class="header-anchor" href="#_4-preview-and-export" aria-label="Permalink to &quot;4. Preview and export&quot;">​</a></h2><p>Switch to <strong>Preview &amp; Export</strong> to check the theme in <strong>Light</strong> and <strong>Dark</strong>: the full palettes, a mock-up of the LCARS chrome, and real Home Assistant controls (buttons, switches, inputs) drawn with your colours.</p><p><img src="'+n+'" alt="Preview &amp; Export: the five palettes in dark mode with their button badges"></p><p>At the bottom, <strong>Copy YAML</strong> copies the finished theme.</p><p><img src="'+i+'" alt="Generated Theme YAML: the instructions and the Copy YAML button above the theme&#39;s YAML"></p><h2 id="_5-add-it-to-ha-lcars" tabindex="-1">5. Add it to HA-LCARS <a class="header-anchor" href="#_5-add-it-to-ha-lcars" aria-label="Permalink to &quot;5. Add it to HA-LCARS&quot;">​</a></h2><p>The theme builds on HA-LCARS&#39;s shared settings (its fonts, chrome and styling), so it goes into HA-LCARS&#39;s own theme file, as HA-LCARS&#39;s own guide to <a href="https://github.com/th3jesta/ha-lcars#make-your-own-color-themes" target="_blank" rel="noreferrer">making your own colour themes</a> describes:</p><ol><li>Open HA-LCARS&#39;s theme file, <code>lcars.yaml</code>, in the <code>themes</code> folder of your Home Assistant configuration.</li><li>Paste the YAML at the very end of the file.</li><li>Reload themes: <strong>Developer tools &gt; YAML &gt; Themes</strong>, or the <code>frontend.reload_themes</code> action.</li><li>Pick your theme in your <strong>Profile</strong> (or set it as the default theme).</li></ol><div class="warning custom-block"><p class="custom-block-title">Keep a copy of your theme</p><p>Updating HA-LCARS (for example through HACS) replaces <code>lcars.yaml</code>, and your theme with it. Keep the YAML somewhere safe and paste it back after an update. To change it later, load it again with <strong>Paste theme YAML</strong>.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>: the ready-made LCARdS profiles</li><li><a href="./alert-mode-lab.html">Alert Mode Lab</a>: how each alert mode recolours your dashboards</li><li><a href="./../core/themes/">Themes</a>: LCARdS theme tokens and the colour palette</li></ul>',26)])])}const b=t(h,[["render",d]]);export{f as __pageData,b as default};
